css:
.sl-hero-journey {
  background-color: var(--smartlearn-card-bg);
  color: var(--smartlearn-text);
  font-family: var(--smartlearn-body-font, system-ui, -apple-system, sans-serif);
  border-bottom: 1px solid var(--smartlearn-card-border);
  background-image: radial-gradient(var(--smartlearn-card-border) 1px, transparent 1px);
  background-size: 20px 20px;
  padding-block: clamp(3rem, 6vw, 4.5rem);
}
.sl-hero-journey .sl-text-primary { color: var(--smartlearn-primary); }
.sl-hero-journey .sl-text-emphasis {
  color: var(--smartlearn-text);
  font-family: var(--smartlearn-heading-font, var(--smartlearn-body-font, system-ui, -apple-system, sans-serif));
}
.sl-hero-journey .sl-text-muted { color: var(--smartlearn-text-muted); }
.sl-hero-journey .sl-bg-main {
  background-color: var(--smartlearn-bg);
  border: 1px solid var(--smartlearn-card-border);
}
.sl-hero-journey .sl-bg-card { background-color: var(--smartlearn-card-bg); }
.sl-hero-journey .sl-bg-primary { background-color: var(--smartlearn-primary); }
.sl-hero-journey .sl-tint-primary {
  background-color: color-mix(in srgb, var(--smartlearn-primary) 15%, transparent);
}
.sl-hero-journey .sl-btn-primary {
  background-color: var(--smartlearn-btn-bg);
  border: 1px solid var(--smartlearn-btn-bg);
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-journey .sl-btn-primary:hover,
.sl-hero-journey .sl-btn-primary:focus-visible {
  background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-primary-hover));
  border-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-primary-hover));
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-journey .sl-journey-title {
  letter-spacing: -0.02em;
}
.sl-hero-journey .sl-course-title {
  letter-spacing: -0.01em;
}
.sl-hero-journey .sl-stat-card {
  min-width: 100px;
  transition: transform 0.2s ease;
}
.sl-hero-journey .sl-stat-caption {
  font-size: 11px;
}
.sl-hero-journey .sl-progress-track {
  height: 12px;
  background-color: var(--smartlearn-card-bg);
  border: 1px solid var(--smartlearn-card-border);
}
.sl-hero-journey .sl-progress-fill {
  transition: width 1s cubic-bezier(0.16, 1, 0.3, 1);
}
.sl-hero-journey .sl-rec-icon {
  width: 48px;
  height: 48px;
  flex-shrink: 0;
}
.sl-hero-journey .sl-rec-item {
  transition: transform 0.2s ease, border-color 0.2s ease, background-color 0.2s ease;
}
.sl-hero-journey .sl-rec-item:hover,
.sl-hero-journey .sl-rec-item:focus-within {
  border-color: var(--smartlearn-primary);
  background-color: color-mix(in srgb, var(--smartlearn-primary) 10%, var(--smartlearn-bg));
}
[dir="rtl"] .sl-hero-journey .sl-rtl-flip {
  transform: scaleX(-1);
}
@media (prefers-reduced-motion: no-preference) {
  .sl-hero-journey .sl-stat-card:hover { transform: translateY(-3px); }
  .sl-hero-journey .sl-rec-item:hover { transform: translateX(5px); }
  [dir="rtl"] .sl-hero-journey .sl-rec-item:hover { transform: translateX(-5px); }
}
@media (prefers-reduced-motion: reduce) {
  .sl-hero-journey .sl-stat-card,
  .sl-hero-journey .sl-rec-item,
  .sl-hero-journey .sl-progress-fill {
    transition: none;
  }
}

js:
(function() {
  'use strict';
  function initStudentJourneyHeroes() {
    var roots = document.querySelectorAll('.sl-hero-journey');
    if (!roots.length) return;
    var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    roots.forEach(function(root) {
      if (root.dataset.slInit === '1') return;
      root.dataset.slInit = '1';
      var bar = root.querySelector('.sl-progress-fill');
      if (!bar) return;
      var target = bar.getAttribute('data-target') || '72%';
      if (reduceMotion) {
        bar.style.width = target;
        return;
      }
      bar.style.width = '0%';
      window.requestAnimationFrame(function() {
        window.setTimeout(function() {
          bar.style.width = target;
        }, 150);
      });
    });
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initStudentJourneyHeroes);
  } else {
    initStudentJourneyHeroes();
  }
})();
